# Let me check if maybe the OR rule applies (either non-zero gives 2)
upper_section = input_grid[:13]
lower_section = input_grid[14:]

# Try rule: 2 if EITHER upper OR lower has non-zero
output_or = []
for r in range(13):
    out_row = []
    for c in range(3):
        if upper_section[r][c] != 0 or lower_section[r][c] != 0:
            out_row.append(2)
        else:
            out_row.append(0)
    output_or.append(out_row)

print("OR rule output:")
for row in output_or:
    print(row)
print(f"Total 2s: {sum(sum(row.count(2) for row in output_or) for _ in range(3))}")

# Also try XOR rule (only ONE has non-zero)
output_xor = []
for r in range(13):
    out_row = []
    for c in range(3):
        upper_nonzero = upper_section[r][c] != 0
        lower_nonzero = lower_section[r][c] != 0
        # XOR: exactly one has non-zero
        if upper_nonzero != lower_nonzero:
            out_row.append(2)
        else:
            out_row.append(0)
    output_xor.append(out_row)

print("\nXOR rule output:")
for row in output_xor:
    print(row)

# Let me try different row alignments
